import { ai } from '@/lib/ai'

const drawShape = {
  name: 'draw_shape',
  description: 'Add an element to the canvas',
  parameters: { type: 'object', properties: { kind: { type: 'string', enum: ['rectangle','ellipse','arrow','text'] }, x: {type:'number'}, y:{type:'number'}, label:{type:'string'} }, required: ['kind','x','y'] },
}

export async function POST(req: Request) {
  const { messages } = await req.json()
  const stream = await ai.stream({ messages, tools: [drawShape] })
  return new Response(stream.toSSE(), { headers: { 'content-type': 'text/event-stream' } })
}

